/* app20: VA practice exam, Simulators page, Autopilot 80/20 command center, visuals injected into Today / AUS / MVLC. */
/* ---------- Practice exam ---------- */
const examHist=()=>store.get("exam_hist",[]);
const shuffle=a=>{const b=a.slice();for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b};
PAGE.exam={html:()=>`<div class="card" style="border-left:4px solid var(--accent,#c9a227)"><h3>VA practice exam <span class="sub">MVLC-based · ${EXAM_BANK.length} questions with explanations · ${EXAM_SIMS.length} randomized scenario simulators · timed exam or study mode</span></h3>
<div class="grid g3"><div><div class="row" style="flex-wrap:wrap;gap:6px"><button class="btn sm" data-mode="quick">Quick 10</button><button class="btn sm" data-mode="full">Full exam (40 · 50 min)</button><button class="btn ghost sm" data-mode="ch">Chapter drill</button><button class="btn ghost sm" data-mode="sim">Scenario simulators</button><button class="btn ghost sm" data-mode="missed">Drill my misses</button></div><div class="row" style="margin-top:6px">${sel("ex_ch","Chapter",Object.entries(EXAM_CH_NAMES).map(([k,v])=>[k,`Ch ${k} — ${v}`]),"2")}${chkf("ex_study","Study mode (explain after each answer)",true)}</div></div><div id="ex_histg"></div><div><div class="mut sm">Last 10 attempts</div><div id="ex_spark"></div><div id="ex_histtxt" class="sm"></div></div></div></div><div id="ex_body"></div>`,
mount(){const body=$("#ex_body");let S=null;let timer=null;
 const paintHist=()=>{const h=examHist();if(h.length){vizLine($("#ex_spark"),h.slice(-10).map(x=>x.pct).concat(h.length<2?[h[h.length-1].pct]:[]),{h:60});$("#ex_histtxt").innerHTML=`Best ${Math.max(...h.map(x=>x.pct))}% · average ${Math.round(h.reduce((a,x)=>a+x.pct,0)/h.length)}% · ${h.length} attempts`;vizGauge($("#ex_histg"),h[h.length-1].pct,{label:"last score",size:140,zones:[[69,"var(--bad)"],[84,"var(--warn)"],[101,"var(--good)"]]})}else{$("#ex_histtxt").textContent="No attempts yet.";$("#ex_histg").innerHTML=""}};paintHist();
 const stop=()=>{if(timer){clearInterval(timer);timer=null}};cleanups.push(stop);
 const start=(mode)=>{stop();const study=$("#ex_study").checked;let qs;if(mode==="quick")qs=shuffle(EXAM_BANK).slice(0,10);else if(mode==="full")qs=shuffle(EXAM_BANK).slice(0,40);else if(mode==="ch")qs=shuffle(EXAM_BANK.filter(q=>q.ch==+$("#ex_ch").value));else if(mode==="missed"){const m=store.get("exam_missed",[]);qs=EXAM_BANK.filter(q=>m.includes(q.q));if(!qs.length)return toast("No misses recorded yet — take a quick 10 first")}
  if(mode==="sim")return sims();S={mode,study:mode==="full"?false:study,qs,i:0,ans:[],t0:Date.now(),limit:mode==="full"?50*60:0};draw();if(S.limit){timer=setInterval(()=>{const left=S.limit-Math.floor((Date.now()-S.t0)/1000);const el=$("#ex_timer");if(el){el.textContent=`${String(Math.floor(left/60)).padStart(2,"0")}:${String(left%60).padStart(2,"0")}`;el.style.color=left<300?"var(--bad)":""}if(left<=0){stop();finish()}},1000)}};
 const draw=()=>{const q=S.qs[S.i];const a=S.ans[S.i];body.innerHTML=`<div class="card"><div class="row"><b>Question ${S.i+1} of ${S.qs.length}</b><span class="tag">Ch ${q.ch} — ${EXAM_CH_NAMES[q.ch]}</span><span class="sp"></span>${S.limit?`<span class="ex-timer" id="ex_timer">50:00</span>`:""}<span class="mut sm">${S.ans.filter(x=>x!=null).length} answered</span></div><div class="bar" style="margin:8px 0"><i style="width:${(S.i)/S.qs.length*100}%"></i></div><p style="font-size:1.05em">${esc(q.q)}</p>${q.o.map((o,j)=>`<a class="ex-opt ${a==null?"":(j===q.a?"ok":(j===a?"bad":""))}" data-j="${j}">${String.fromCharCode(65+j)}. ${esc(o)}</a>`).join("")}
  ${a!=null&&S.study?`<div class="card" style="margin-top:10px;border-left:4px solid ${a===q.a?"var(--good)":"var(--bad)"}"><b>${a===q.a?"Correct.":"Not quite — the answer is "+String.fromCharCode(65+q.a)+"."}</b> ${esc(q.e)}<div class="mut sm">Cite: ${esc(q.c)}</div></div>`:""}
  <div class="row" style="margin-top:10px"><button class="btn ghost sm" id="ex_prev" ${S.i===0?"disabled":""}>← Back</button><span class="sp"></span>${S.i<S.qs.length-1?`<button class="btn sm" id="ex_next">Next →</button>`:`<button class="btn sm" id="ex_fin">Finish &amp; score</button>`}</div></div>`;
  $$(".ex-opt").forEach(o=>o.onclick=()=>{if(S.ans[S.i]!=null&&S.study)return;S.ans[S.i]=+o.dataset.j;if(S.study)draw();else{$$(".ex-opt").forEach(x=>x.classList.toggle("sel",x===o))}});$("#ex_prev").onclick=()=>{S.i--;draw()};const n=$("#ex_next");if(n)n.onclick=()=>{S.i++;draw()};const f=$("#ex_fin");if(f)f.onclick=finish};
 const finish=()=>{stop();const res=S.qs.map((q,i)=>({q,a:S.ans[i],ok:S.ans[i]===q.a}));const pct=Math.round(res.filter(r=>r.ok).length/res.length*100);const h=examHist();h.push({d:new Date().toISOString().slice(0,10),pct,n:res.length,mode:S.mode});store.set("exam_hist",h.slice(-50));const missed=new Set(store.get("exam_missed",[]));res.forEach(r=>{if(!r.ok)missed.add(r.q.q);else missed.delete(r.q.q)});store.set("exam_missed",[...missed]);paintHist();
  const byCh={};res.forEach(r=>{byCh[r.q.ch]=byCh[r.q.ch]||{n:0,ok:0};byCh[r.q.ch].n++;if(r.ok)byCh[r.q.ch].ok++});
  body.innerHTML=`<div class="card"><div class="row"><div id="ex_g"></div><div class="sp"><h3 style="margin:0">${pct>=85?"Pass — certification-ready":pct>=70?"Pass — review the misses":"Below passing — drill the weak chapters"}</h3><div class="mut">${res.filter(r=>r.ok).length}/${res.length} correct · ${Math.round((Date.now()-S.t0)/60000)} min · ${S.mode}</div><div class="row" style="margin-top:8px"><button class="btn sm" id="ex_again">Retake</button><button class="btn ghost sm" id="ex_dm">Drill my misses (${missed.size})</button><button class="btn ghost sm" id="ex_copy">Copy report</button></div></div></div>
  <h4>By chapter</h4><div class="row" style="flex-wrap:wrap;gap:14px">${Object.entries(byCh).map(([c,v])=>`<div style="text-align:center"><div id="ex_r${c}"></div></div>`).join("")}</div></div>
  <div class="card"><h4>Review — every question with the explanation</h4>${res.map((r,i)=>`<div style="padding:8px 0;border-bottom:1px solid var(--line)"><div><span class="tag ${r.ok?"good":"bad"}">${r.ok?"✓":"✗"}</span> <b>${i+1}. ${esc(r.q.q)}</b></div><div class="sm">Your answer: ${r.a==null?"<i>blank</i>":esc(r.q.o[r.a])} · Correct: <b>${esc(r.q.o[r.q.a])}</b></div><div class="sm">${esc(r.q.e)} <span class="mut">(${esc(r.q.c)})</span></div></div>`).join("")}</div>`;
  vizGauge($("#ex_g"),pct,{label:"score",size:150,zones:[[69,"var(--bad)"],[84,"var(--warn)"],[101,"var(--good)"]]});Object.entries(byCh).forEach(([c,v])=>vizRing($("#ex_r"+c),v.ok/v.n*100,{label:`Ch ${c} ${EXAM_CH_NAMES[c]}`,size:76,zones:[[69,"var(--bad)"],[84,"var(--warn)"],[101,"var(--good)"]]}));
  $("#ex_again").onclick=()=>start(S.mode);$("#ex_dm").onclick=()=>start("missed");$("#ex_copy").onclick=()=>copy(`VA practice exam ${new Date().toLocaleDateString()} — ${pct}%\n`+res.map((r,i)=>`${r.ok?"✓":"✗"} ${i+1}. ${r.q.q}\n   Answer: ${r.q.o[r.q.a]}\n   ${r.q.e} (${r.q.c})`).join("\n"))};
 const sims=()=>{let cur=EXAM_SIMS[0].id;let item=null;const sd=()=>{const sim=EXAM_SIMS.find(s=>s.id===cur);item=sim.gen();body.innerHTML=`<div class="card"><div class="tabs">${EXAM_SIMS.map(s=>`<button data-s="${s.id}" class="${s.id===cur?"on":""}">${s.title}</button>`).join("")}</div><p style="font-size:1.05em;margin-top:12px">${esc(item.q)}</p><div class="row">${numf("ex_sa","Your answer"+(item.unit?" ("+item.unit+")":" ($)"),"",item.unit?0.01:1)}<button class="btn sm" id="ex_sck" style="align-self:flex-end">Check</button><button class="btn ghost sm" id="ex_snew" style="align-self:flex-end">New scenario</button></div><div id="ex_sout"></div></div>`;
   $$("#ex_body .tabs button").forEach(b=>b.onclick=()=>{cur=b.dataset.s;sd()});$("#ex_snew").onclick=sd;$("#ex_sck").onclick=()=>{const v=val("ex_sa");const ok=Math.abs(v-item.ans)<=item.tol;$("#ex_sout").innerHTML=`<div class="card" style="border-left:4px solid ${ok?"var(--good)":"var(--bad)"}"><b>${ok?"Correct":"Not yet"} — answer ${item.unit?item.ans+" "+item.unit:money2(item.ans)}</b><ol>${item.steps.map(s=>`<li>${esc(s)}</li>`).join("")}</ol><div class="mut sm">Cite: ${esc(item.cite)}</div></div>`;vizPop($("#ex_sout .card"))}};sd()};
 $$("[data-mode]").forEach(b=>b.onclick=()=>start(b.dataset.mode));body.innerHTML=`<div class="card"><p>Pick a mode above. <b>Quick 10</b> for a daily warm-up, <b>Full exam</b> for a timed 40-question simulation (explanations at the end), <b>Chapter drill</b> to work one chapter, <b>Scenario simulators</b> for randomized entitlement, residual, fee, joint-loan, concession and seasoning math with worked steps, and <b>Drill my misses</b> to retest what you got wrong.</p></div>`}};
/* ---------- Simulators ---------- */
const SIM_TABS=[["deal","Deal simulator"],["shock","Rate shock"],["funnel","Pipeline funnel"],["cap","Capacity 80/20"]];
PAGE.sims={html:()=>`<div class="card"><h3>Simulators <span class="sub">live sliders · animated gauges · what-if before the client call</span></h3><div class="tabs" id="sm_tabs">${SIM_TABS.map(t=>`<button data-t="${t[0]}">${t[1]}</button>`).join("")}</div></div><div id="sm_body"></div>`,
mount(){let cur=store.get("simtab","deal");const body=$("#sm_body");const rng=(id,l,min,max,v,step=1,fmt=x=>x)=>`<div><label>${l}: <b id="${id}_v">${fmt(v)}</b></label><input type="range" id="${id}" min="${min}" max="${max}" value="${v}" step="${step}"></div>`;
 const T={
 deal:()=>`<div class="grid g2"><div class="card"><h4>Inputs</h4>${rng("sd_price","Purchase price",150000,1500000,650000,5000,money)}${rng("sd_rate","Rate",4,9,6.25,0.125,x=>x+"%")}${rng("sd_dp","Down payment",0,25,0,1,x=>x+"%")}${rng("sd_inc","Gross monthly income",3000,30000,14000,100,money)}${rng("sd_debt","Monthly debts",0,4000,600,25,money)}${rng("sd_fam","Family size",1,7,3)}${rng("sd_sqft","Living area sq ft",700,4500,1900,50)}<div class="grid2">${sel("sd_st","State",Object.keys(MVLC_REGION_OF).sort().map(s=>[s,s]),"CA")}${sel("sd_ff","Funding fee class",[["2.15","First use"],["3.3","Subsequent"],["0","Exempt"]],"2.15")}</div></div>
  <div class="card"><h4>Live readout</h4><div class="row" style="flex-wrap:wrap;justify-content:space-around"><div id="sd_g1"></div><div id="sd_g2"></div><div id="sd_g3"></div></div><div id="sd_out"></div></div></div>`,
 shock:()=>`<div class="grid g2"><div class="card"><h4>Inputs</h4>${rng("sh_loan","Loan amount",100000,1500000,600000,5000,money)}${rng("sh_rate","Current quote",4,9,6.5,0.125,x=>x+"%")}${rng("sh_term","Term (years)",10,30,30,5)}<p class="mut sm">Drag the quote — the curve shows P&amp;I from 4% to 9%; the readout shows what a 0.25% and 1% move does to payment and to the income needed at 41% DTI.</p></div><div class="card"><h4>Payment vs rate</h4><div id="sh_line"></div><div id="sh_out"></div></div></div>`,
 funnel:()=>`<div class="grid g2"><div class="card"><h4>Inputs (monthly)</h4>${rng("fn_leads","New leads / month",10,600,120,5)}${rng("fn_c","Contact rate",10,100,70,1,x=>x+"%")}${rng("fn_a","Appointment / consult rate",10,100,45,1,x=>x+"%")}${rng("fn_p","Application rate",10,100,60,1,x=>x+"%")}${rng("fn_u","Approval rate",30,100,85,1,x=>x+"%")}${rng("fn_k","Close rate",30,100,80,1,x=>x+"%")}${rng("fn_loan","Average loan",200000,1200000,520000,10000,money)}${rng("fn_bps","Comp (bps)",50,300,150,5)}</div><div class="card"><h4>Funnel</h4><div id="fn_f"></div><div class="grid g3" id="fn_k"></div><h4>12-month closings at this conversion</h4><div id="fn_line"></div></div></div>`,
 cap:()=>`<div class="grid g2"><div class="card"><h4>Where Steven's minutes go per file</h4>${rng("cp_files","Closings / month",4,120,25,1)}${AP_STAGES.map((s,i)=>`<div class="row sm" style="padding:4px 0;border-bottom:1px solid var(--line)"><span class="sp">${esc(s.l)} <span class="mut">(${esc(s.who)})</span></span><label class="chk"><input type="checkbox" class="cp_auto" data-i="${i}" ${s.auto?"checked":""}>automated</label><span class="mut" style="width:70px;text-align:right">${s.lo} min</span></div>`).join("")}<p class="mut sm">Unchecking a stage puts its minutes back on Steven. Agent/ISA minutes are shown for the whole team.</p></div><div class="card"><h4>Result</h4><div class="row" style="justify-content:space-around"><div id="cp_g"></div><div id="cp_k"></div></div><div id="cp_share"></div><div id="cp_out"></div></div></div>`};
 const wire=()=>{$$("input[type=range]").forEach(r=>{const lab=$("#"+r.id+"_v");r.oninput=()=>{if(lab){const f={sd_price:money,sd_inc:money,sd_debt:money,sh_loan:money,fn_loan:money}[r.id];lab.textContent=f?f(+r.value):(/rate|_c$|_a$|_p$|_u$|_k$|_dp$/.test(r.id)?r.value+"%":r.value)}calc()}});$$("select").forEach(s=>s.onchange=calc);$$(".cp_auto").forEach(c=>c.onchange=calc);calc()};
 const calc=()=>{if(cur==="deal"){const P=val("sd_price"),rate=val("sd_rate"),dp=val("sd_dp"),inc=val("sd_inc"),debt=val("sd_debt"),fam=val("sd_fam"),sq=val("sd_sqft"),st=$("#sd_st").value;let ff=+$("#sd_ff").value;if(ff&&dp>=10)ff=1.25;else if(ff&&dp>=5)ff=1.5;const base=P*(1-dp/100),fee=base*ff/100,L=base+fee;const pi=pmt(L,rate/100,360),ti=P*0.011/12+P*0.0035/12,piti=pi+ti;const dti=(piti+debt)/inc*100;const tax=inc*0.18;const resid=inc-tax-piti-sq*0.14-debt;const req=mvlcResidualReq(st,fam,L);const rp=resid/req*100;const need120=dti>41;const okRes=resid>=(need120?req*1.2:req);const like=Math.max(5,Math.min(98,Math.round(60+(okRes?20:-25)+(dti<=41?15:dti<=50?0:-20)+(dp>=5?5:0))));
   vizGauge($("#sd_g1"),Math.min(100,dti),{label:"DTI",size:150,fmt:n=>n.toFixed(1)+"%",zones:[[41,"var(--good)"],[50,"var(--warn)"],[101,"var(--bad)"]]});vizGauge($("#sd_g2"),Math.min(100,rp/2),{label:"residual vs guideline",size:150,fmt:n=>Math.round(n*2)+"%",zones:[[50,"var(--bad)"],[60,"var(--warn)"],[101,"var(--good)"]]});vizGauge($("#sd_g3"),like,{label:"approval likelihood",size:150});
   $("#sd_out").innerHTML=`<table><tbody><tr><td>Base loan / funding fee ${ff}% / total</td><td>${money(base)} / ${money2(fee)} / <b>${money(L)}</b></td></tr><tr><td>P&amp;I · taxes+insurance · PITI</td><td>${money2(pi)} · ${money2(ti)} · <b>${money2(piti)}</b></td></tr><tr><td>DTI</td><td><b>${dti.toFixed(1)}%</b> ${dti>41?"→ needs 120% residual or tax-free justification":""}</td></tr><tr><td>Residual (est. taxes 18%, maint ${money2(sq*0.14)})</td><td><b>${money(resid)}</b> vs ${money(req)}${need120?` (120% = ${money(req*1.2)})`:""} → ${okRes?"✓":"✗"}</td></tr><tr><td>Max seller concessions (4%)</td><td>${money(P*0.04)} + unlimited non-recurring costs</td></tr><tr><td>Fix-it levers</td><td class="sm">${[dti>41&&!okRes?"pay down "+money(Math.ceil(Math.max(0,(piti+debt-inc*0.41))))+"/mo of debt or add income":"",dp<5&&ff>0?"5% down drops the fee to 1.50% (saves "+money(base*(ff-1.5)/100)+")":"",!okRes?"lower price "+money(Math.ceil(Math.max(0,(req*(need120?1.2:1)-resid))/ (pmt(1,rate/100,360)+0.0145/12)/1000)*1000)+" or buy down the rate":"","seller-paid funding fee inside the 4% cap"].filter(Boolean).map(x=>"• "+x).join("<br>")||"Clean file — write it"}</td></tr></tbody></table>`}
  else if(cur==="shock"){const L=val("sh_loan"),r=val("sh_rate"),n=val("sh_term")*12;const rates=[];for(let x=4;x<=9.001;x+=0.25)rates.push(x);const vals=rates.map(x=>pmt(L,x/100,n));const idx=Math.round((r-4)/0.25);vizLine($("#sh_line"),vals,{h:150,marker:Math.max(0,Math.min(vals.length-1,idx))});const cur$=pmt(L,r/100,n);$("#sh_out").innerHTML=`<table><tbody><tr><td>At ${r}%</td><td><b>${money2(cur$)}</b> P&amp;I · income needed at 41% DTI (no other debt, +1.45% tax/ins) ≈ ${money((cur$+L*0.0145/12)/0.41)}/mo</td></tr><tr><td>+0.25%</td><td>${money2(pmt(L,(r+0.25)/100,n))} (+${money2(pmt(L,(r+0.25)/100,n)-cur$)}/mo)</td></tr><tr><td>+1.00%</td><td>${money2(pmt(L,(r+1)/100,n))} (+${money2(pmt(L,(r+1)/100,n)-cur$)}/mo · ${money(Math.round((pmt(L,(r+1)/100,n)-cur$)*12*30))} over the term)</td></tr><tr><td>−0.50% (buydown/IRRRL)</td><td>${money2(pmt(L,(r-0.5)/100,n))} (saves ${money2(cur$-pmt(L,(r-0.5)/100,n))}/mo · recoups 2 points (${money(L*0.02)}) in ${Math.ceil(L*0.02/Math.max(1,cur$-pmt(L,(r-0.5)/100,n)))} months)</td></tr></tbody></table>`}
  else if(cur==="funnel"){const leads=val("fn_leads");const st=[["Leads",leads],["Contacted",leads*val("fn_c")/100],["Consults",0],["Applications",0],["Approvals",0],["Closings",0]];st[2][1]=st[1][1]*val("fn_a")/100;st[3][1]=st[2][1]*val("fn_p")/100;st[4][1]=st[3][1]*val("fn_u")/100;st[5][1]=st[4][1]*val("fn_k")/100;vizFunnel($("#fn_f"),st.map(s=>({l:s[0],v:Math.round(s[1]*10)/10})),{fmt:v=>v.toFixed(1)});const closes=st[5][1],vol=closes*val("fn_loan"),rev=vol*val("fn_bps")/10000;$("#fn_k").innerHTML=[["Closings / mo",closes.toFixed(1)],["Volume / mo",money(vol)],["Revenue / mo",money(rev)],["Lead → close",(closes/leads*100).toFixed(1)+"%"],["Annual closings",Math.round(closes*12)],["Annual revenue",money(rev*12)]].map(([k,v])=>`<div class="card kpi" style="margin:0"><div class="k">${k}</div><div class="v" style="font-size:18px">${v}</div></div>`).join("");vizLine($("#fn_line"),Array.from({length:12},(_,i)=>closes*(0.6+0.4*Math.min(1,(i+1)/6))),{h:90})}
  else if(cur==="cap"){const files=val("cp_files");const auto=[...$$(".cp_auto")].map(c=>c.checked);let lo=0,team=0,ai=0;AP_STAGES.forEach((s,i)=>{if(auto[i]){lo+=s.lo*(1-s.autoPct);team+=s.team;ai+=s.lo*s.autoPct*0.3}else{lo+=s.lo;team+=s.team*0.6}});const loH=lo*files/60/4.33,teamH=team*files/60/4.33,aiH=ai*files/60/4.33;const total=loH+teamH+aiH;const pct=Math.round((1-loH/total)*100);vizGauge($("#cp_g"),pct,{label:"runs without Steven",size:160,zones:[[60,"var(--bad)"],[79,"var(--warn)"],[101,"var(--good)"]]});$("#cp_k").innerHTML=`<div class="card kpi" style="margin:0"><div class="k">Steven hrs/week</div><div class="v">${loH.toFixed(1)}</div><div class="d">${(lo).toFixed(0)} min per file</div></div>`;vizShare($("#cp_share"),[{l:"AI agents",v:aiH,c:"var(--good)"},{l:"ISA / EA / processor",v:teamH,c:"var(--acc2,#0ea5e9)"},{l:"Steven",v:loH,c:"var(--warn)"}]);$("#cp_out").innerHTML=`<p class="sm">${pct>=80?"At or above the 80/20 target.":"Below 80/20 — the unchecked stages above are where Steven's hours come from; turn on their automations in Autopilot."} Steven's licensed minutes per file: consult, lock/pricing, tough-file path, CD call. Everything else is agent-drafted and ISA-run.</p>`}};
 const draw=()=>{$$("#sm_tabs button").forEach(b=>b.classList.toggle("on",b.dataset.t===cur));body.innerHTML=T[cur]();wire()};$$("#sm_tabs button").forEach(b=>b.onclick=()=>{cur=b.dataset.t;store.set("simtab",cur);draw()});draw()}};
/* ---------- Autopilot 80/20 ---------- */
const AP_STAGES=[{l:"Lead capture & scoring",who:"AI agents",color:"var(--good)",lo:0,team:5,autoPct:1,auto:true},{l:"Speed-to-lead contact",who:"ISA (5-min SLA)",color:"var(--acc2,#0ea5e9)",lo:2,team:20,autoPct:0.9,auto:true},{l:"Pre-qual & COE pull",who:"AI + ISA",color:"var(--good)",lo:3,team:25,autoPct:0.85,auto:true},{l:"Consult (15 min)",who:"Steven",color:"var(--warn)",lo:20,team:5,autoPct:0.15,auto:true},{l:"Application & disclosures",who:"ISA + Arive",color:"var(--acc2,#0ea5e9)",lo:3,team:45,autoPct:0.8,auto:true},{l:"Docs & income analysis",who:"AI docproc + processor",color:"var(--good)",lo:5,team:60,autoPct:0.9,auto:true},{l:"Pricing & lock",who:"Steven (decision)",color:"var(--warn)",lo:10,team:5,autoPct:0.3,auto:true},{l:"Appraisal & conditions",who:"Processor + agents",color:"var(--good)",lo:8,team:70,autoPct:0.8,auto:true},{l:"CD review call",who:"Steven",color:"var(--warn)",lo:12,team:10,autoPct:0.2,auto:true},{l:"Closing & post-close nurture",who:"TC + agents",color:"var(--good)",lo:3,team:30,autoPct:0.9,auto:true}];
const AP_RULES_DEFAULT=[
{id:"r1",min:{ai:10,isa:15,lo:0},trigger:"New lead arrives (any source)",agent:"Lead Scorer → enrich, score, tag program",isa:"Call within 5 min, run qualification script, book consult",steven:"Only if lead asks for licensed advice before consult",on:true},
{id:"r2",min:{ai:20,isa:10,lo:15},trigger:"Consult booked",agent:"Vanessa pulls COE (WebLGY), credit soft-pull, builds scenario + MVLC entitlement math",isa:"Confirms docs list sent, 24-hr reminder",steven:"15-minute consult (Layer 1)",on:true},
{id:"r3",min:{ai:30,isa:40,lo:0},trigger:"Consult done, path chosen",agent:"ARIVE application pre-filled, disclosures queued, needs-list generated",isa:"Walks borrower through e-sign, collects docs",steven:"None",on:true},
{id:"r4",min:{ai:45,isa:40,lo:3},trigger:"Docs received",agent:"Document Processor extracts income/assets, runs AUS simulator, QC auditor flags",isa:"Chases missing items, clears simple conditions",steven:"Only red-flag or overlay exceptions (UW advocacy memo drafted by agent)",on:true},
{id:"r5",min:{ai:10,isa:5,lo:3},trigger:"Rate lock window / market move",agent:"Rate Watcher alerts with Home Report lean, drafts lock recommendation",isa:"Schedules 5-min lock call if needed",steven:"Lock decision (Layer 1) — one tap approve",on:true},
{id:"r6",min:{ai:30,isa:30,lo:4},trigger:"Appraisal ordered / NOV issued",agent:"Tidewater comp package prepped from MLS; MPR repair list drafted; ROV letter template",isa:"Coordinates agents, 48-hour Tidewater response",steven:"ROV strategy only if value gap > 2%",on:true},
{id:"r7",min:{ai:15,isa:30,lo:2},trigger:"Conditional approval",agent:"Conditions parsed, owner assigned, borrower status email drafted",isa:"Clears borrower conditions, updates Zoho",steven:"None unless lender exception needed",on:true},
{id:"r8",min:{ai:15,isa:20,lo:10},trigger:"CD issued",agent:"CD vs LE variance check, fee QC (allowables/1% rule), cash-to-close explainer",isa:"Schedules signing, confirms wire instructions verbally",steven:"CD review call (10 min)",on:true},
{id:"r9",min:{ai:20,isa:10,lo:0},trigger:"Funded",agent:"Review request, 30/90/365 nurture, IRRRL watch enrolled, funding-fee refund check if rating pending",isa:"Thank-you call, referral ask",steven:"None",on:true},
{id:"r10",min:{ai:30,isa:30,lo:2},trigger:"Rate drops ≥0.50% vs a past client",agent:"Refi Hunter builds IRRRL recoup/NTB test, drafts compliant letter → Compliance gate",isa:"Calls top 10 by savings",steven:"Approves letter batch (15-min block)",on:true},
{id:"r11",min:{ai:30,isa:20,lo:15},trigger:"Daily 06:45",agent:"Vanessa compiles approvals queue, brief, pipeline risks, agent activity",isa:"Reviews day plan, owns the call list",steven:"15-minute approvals block",on:true},
{id:"r12",min:{ai:30,isa:30,lo:20},trigger:"Weekly Friday",agent:"Scale Engine metrics, grant watcher diff, QC sample audit",isa:"Capacity audit",steven:"20-minute retro",on:true}];
/* minute-weighted: when a rule is off, its agent minutes fall to Steven and half of the ISA minutes too */
const apMinutes=(rules)=>{let ai=0,isa=0,lo=0;rules.forEach(r=>{const m=r.min||AP_RULES_DEFAULT.find(x=>x.id===r.id)?.min||{ai:0,isa:0,lo:0};if(r.on){ai+=m.ai;isa+=m.isa;lo+=m.lo}else{lo+=m.lo+m.ai*0.6+m.isa*0.5;isa+=m.isa*0.5}});return{ai,isa,lo,pct:Math.round((1-lo/((ai+isa+lo)||1))*100)}};
const apRules=()=>{const saved=store.get("ap_rules");return saved||AP_RULES_DEFAULT.map(r=>({...r}))};
const apQueue=()=>{const q=[];approvals.filter(a=>!a.decision).forEach(a=>q.push({k:"approval",id:a.id,t:`${a.type} — ${a.who}`,d:`${a.agent} · ${a.note}`,st:a.status}));tasks.forEach((t,i)=>{if(!t.done&&t.p==="high")q.push({k:"task",id:i,t:t.t,d:"high-priority task",st:"TASK"})});store.get("ap_esc",[]).forEach((e,i)=>q.push({k:"esc",id:i,t:e.t,d:"escalated by ISA · "+e.d,st:"ESC"}));return q};
PAGE.autopilot={html:()=>`<div class="card" style="border-left:4px solid var(--accent,#c9a227)"><div class="row" style="flex-wrap:wrap;gap:16px;align-items:center"><div id="ap_g"></div><div class="sp"><h3 style="margin:0">Autopilot — the 80/20 operating model <span class="sub">agents draft and run · Vanessa routes · ISA/EA owns conversations · Steven does only the licensed 20%</span></h3><div class="row" style="margin-top:8px;flex-wrap:wrap"><button class="btn sm" id="ap_run">▶ Run morning autopilot</button><button class="btn ghost sm" id="ap_sim">Simulate a day (100 events)</button><button class="btn ghost sm" id="ap_docx">⬇ Operating model (.docx)</button><span class="mut sm" id="ap_simout"></span></div></div><div id="ap_share" style="min-width:260px"></div></div></div>
<div class="card"><h3>Loan flow — who touches each stage <span class="sub">green = agents, blue = ISA/EA/processor, gold = Steven's licensed minutes</span></h3><div id="ap_flow"></div></div>
<div class="grid g2"><div class="card"><h3>Steven's 20% — needs you now <span class="sub" id="ap_qn"></span></h3><div class="ap-queue" id="ap_q"></div><div class="row" style="margin-top:8px"><input id="ap_esct" placeholder="ISA escalation (what needs Steven?)" style="flex:1"><button class="btn ghost sm" id="ap_escb">Escalate</button></div></div>
<div class="card"><h3>Delegated to the team <span class="sub">ISA / EA / processor queue</span></h3><div id="ap_isa"></div><h4 style="margin-top:12px">Standing Layer-1 duties</h4><ul class="sm" style="margin:0 0 0 18px">${STEVEN_ONLY.map(s=>`<li>${esc(s)}</li>`).join("")}</ul></div></div>
<div class="card"><h3>Handoff rules <span class="sub">trigger → agent does → ISA does → Steven's gate · toggle to see the 80/20 effect</span></h3><table id="ap_rules"></table></div>
<div class="grid g2"><div class="card"><h3>Agent activity</h3><div id="ap_feed" style="max-height:260px;overflow:auto"></div></div><div class="card"><h3>Hours per week by owner <span class="sub">from the delegation map</span></h3><div id="ap_hours"></div><div id="ap_kpi" class="grid g3" style="margin-top:8px"></div></div></div>`,
mount(){const rules=apRules();const share=()=>{const m=apMinutes(rules);vizGauge($("#ap_g"),m.pct,{label:"runs without Steven (minutes per file)",size:170,zones:[[60,"var(--bad)"],[79,"var(--warn)"],[101,"var(--good)"]]});vizShare($("#ap_share"),[{l:"AI agents + Vanessa",v:m.ai,c:"var(--good)"},{l:"ISA / EA / processor / TC",v:m.isa,c:"var(--acc2,#0ea5e9)"},{l:"Steven",v:m.lo,c:"var(--warn)"}]);return m.pct};share();
 vizFlow($("#ap_flow"),AP_STAGES.map(s=>({l:s.l,who:s.who,color:s.color,n:s.lo?s.lo+" min":"0 min"})));
 const q=()=>{const items=apQueue();$("#ap_qn").textContent=`${items.length} item${items.length===1?"":"s"} · target ≤ 15 min`;$("#ap_q").innerHTML=items.map(it=>`<div class="row"><div class="sp"><b>${esc(it.t)}</b><div class="mut sm">${esc(it.d)}</div></div><span class="tag ${it.st==="PASS"||it.st==="TASK"?"good":it.st==="FIX"||it.st==="ESC"?"warn":"bad"}">${it.st}</span>${it.k==="approval"?`<button class="btn good sm" data-k="approval" data-id="${it.id}" data-d="approved">Approve</button><button class="btn ghost sm" data-k="approval" data-id="${it.id}" data-d="rejected">Reject</button>`:it.k==="task"?`<button class="btn good sm" data-k="task" data-id="${it.id}" data-d="done">Done</button><button class="btn ghost sm" data-k="task" data-id="${it.id}" data-d="isa">→ ISA</button>`:`<button class="btn good sm" data-k="esc" data-id="${it.id}" data-d="done">Handled</button><button class="btn ghost sm" data-k="esc" data-id="${it.id}" data-d="isa">→ ISA</button>`}</div>`).join("")||`<p class="mut">Inbox zero — the system is running.</p>`;
  $$("#ap_q button").forEach(b=>b.onclick=()=>{const {k,id,d}=b.dataset;if(k==="approval"){const a=approvals.find(x=>x.id==id);if(a.status==="BLOCK"&&d==="approved")return toast("Compliance BLOCK — cannot approve");a.decision=d;persist();updateBadge()}else if(k==="task"){if(d==="done")tasks[id].done=true;else{const isa=store.get("ap_isa",[]);isa.push({t:tasks[id].t,from:"Steven",d:new Date().toLocaleDateString()});store.set("ap_isa",isa);tasks[id].done=true}persist()}else{const e=store.get("ap_esc",[]);const [it]=e.splice(id,1);store.set("ap_esc",e);if(d==="isa"){const isa=store.get("ap_isa",[]);isa.push({t:it.t,from:"escalation returned",d:new Date().toLocaleDateString()});store.set("ap_isa",isa)}}q();isaQ();toast("Logged")});};q();
 const isaQ=()=>{const isa=store.get("ap_isa",[]);$("#ap_isa").innerHTML=isa.length?isa.map((x,i)=>`<div class="row sm" style="padding:6px 0;border-bottom:1px solid var(--line)"><span class="sp">${esc(x.t)} <span class="mut">(${esc(x.from)} · ${esc(x.d)})</span></span><button class="btn ghost sm" data-i="${i}">✓</button></div>`).join(""):`<p class="mut sm">Nothing delegated right now. Use "→ ISA" on an item in your queue.</p>`;$$("#ap_isa button").forEach(b=>b.onclick=()=>{const a=store.get("ap_isa",[]);a.splice(+b.dataset.i,1);store.set("ap_isa",a);isaQ()})};isaQ();
 $("#ap_escb").onclick=()=>{const t=$("#ap_esct").value.trim();if(!t)return;const e=store.get("ap_esc",[]);e.push({t,d:new Date().toLocaleTimeString()});store.set("ap_esc",e);$("#ap_esct").value="";q()};
 const drawRules=()=>{$("#ap_rules").innerHTML=`<thead><tr><th>On</th><th>Trigger</th><th>Agent does</th><th>ISA / EA does</th><th>Steven's gate</th></tr></thead><tbody>${rules.map(r=>`<tr style="${r.on?"":"opacity:.5"}"><td><label class="chk"><input type="checkbox" data-r="${r.id}" ${r.on?"checked":""}></label></td><td><b>${esc(r.trigger)}</b></td><td class="sm">${esc(r.agent)}</td><td class="sm">${esc(r.isa)}</td><td class="sm" style="color:${/^None/.test(r.steven)?"var(--good)":"var(--warn)"}">${esc(r.steven)}</td></tr>`).join("")}</tbody>`;$$("#ap_rules input").forEach(c=>c.onchange=()=>{rules.find(r=>r.id===c.dataset.r).on=c.checked;store.set("ap_rules",rules);drawRules();share()})};drawRules();
 const feed=$("#ap_feed");const pushFeed=(t,who)=>{feed.insertAdjacentHTML("afterbegin",`<div class="row sm" style="padding:4px 0;border-bottom:1px solid var(--line);animation:rise .4s both"><span class="ap-who">${esc(who)}</span><span class="sp">${esc(t)}</span><span class="mut">${new Date().toLocaleTimeString()}</span></div>`);while(feed.children.length>40)feed.lastChild.remove()};
 const on=AGENTS.filter(a=>a.on);on.slice(0,8).forEach(a=>pushFeed(a.last,a.name.split(" ·")[0]));
 $("#ap_run").onclick=()=>{const steps=[["Vanessa","Pulling overnight leads from Zoho, scoring and tagging programs…"],["Lead Scorer","7 new leads scored · 3 hot (≥70) · ISA call list built"],["COE Agent","2 COEs auto-issued via WebLGY · 1 needs DD-214 (ISA tasked)"],["Document Processor","4 files: income/assets extracted · AUS simulator run · 1 residual shortfall flagged"],["Rate Watcher","Home Report lean: lock · 2 files inside lock window → lock recommendations drafted"],["Refi Hunter","IRRRL scan: 5 past clients ≥0.50% drop · letters drafted → Compliance gate"],["Grant Watcher","CalHFA page diff: no change · 1 county DPA reopened"],["Compliance","6 consumer pieces reviewed · 5 PASS · 1 FIX (missing NMLS)"],["Vanessa","Approvals queue ready — 15-minute block: 4 items need Steven"]];let i=0;const iv=setInterval(()=>{if(i>=steps.length){clearInterval(iv);toast("Morning autopilot complete — queue updated");q();return}pushFeed(steps[i][1],steps[i][0]);i++},550);cleanups.push(()=>clearInterval(iv))};
 $("#ap_sim").onclick=()=>{let lo=0,ai=0,isa=0,n=0;const keys=["new lead","consult booked","consult done","docs received","rate lock","appraisal","conditional","cd issued","funded","rate drops"];for(let i=0;i<100;i++){const k=keys[Math.floor(Math.random()*keys.length)];const r=rules.find(x=>x.trigger.toLowerCase().includes(k));if(!r)continue;const m=r.min;if(r.on){ai+=m.ai;isa+=m.isa;const gate=/^None/.test(r.steven)?(Math.random()<0.05?15:0):/only|unless/i.test(r.steven)?(Math.random()<0.25?m.lo+10:0):m.lo;lo+=gate;if(gate)n++}else{lo+=m.lo+m.ai*0.6+m.isa*0.5;isa+=m.isa*0.5;n++}}const tot=ai+isa+lo||1;const pct=Math.round((1-lo/tot)*100);$("#ap_simout").innerHTML=`100 events → agents ${Math.round(ai/60)} h · team ${Math.round(isa/60)} h · <b>Steven ${(lo/60).toFixed(1)} h across ${n} touches</b> = ${pct}% ran without you ${pct>=80?"✓":"— turn rules back on"}`;vizPop($("#ap_simout").closest(".card"))};
 const B=MLO_TIME.after;const loH=B.reduce((a,x)=>a+x[1],0);vizShare($("#ap_hours"),[{l:"AI agents (est.)",v:60,c:"var(--good)"},{l:"ISA / EA / processor / TC",v:95,c:"var(--acc2,#0ea5e9)"},{l:"Steven",v:loH,c:"var(--warn)"}]);$("#ap_kpi").innerHTML=[["Steven hrs/wk",loH+" h"],["Approvals block","15 min/day"],["Friday retro","20 min"]].map(([k,v])=>`<div class="card kpi" style="margin:0"><div class="k">${k}</div><div class="v" style="font-size:18px">${v}</div></div>`).join("");
 $("#ap_docx").onclick=()=>saveFile("autopilot-operating-model.docx",docxBytes([{t:"Autopilot — 80/20 operating model",h:1},{t:"Loan flow and owners",h:2},...AP_STAGES.map(s=>({t:`${s.l} — ${s.who} — Steven ${s.lo} min/file`})),{t:"Handoff rules",h:2},...rules.map(r=>({t:`[${r.on?"ON":"off"}] ${r.trigger}: agent — ${r.agent}; ISA — ${r.isa}; Steven — ${r.steven}`})),{t:"Steven only (Layer 1)",h:2},...STEVEN_ONLY.map(s=>({t:"• "+s}))]))}};
/* ---------- inject visuals: Today strip, AUS gauge, MVLC residual gauge, MVLC exam link ---------- */
{const h0=PAGE.today.html,m0=PAGE.today.mount;PAGE.today.html=()=>`<div class="card" style="border-left:4px solid var(--accent,#c9a227);margin-bottom:14px"><div class="row" style="flex-wrap:wrap;gap:14px;align-items:center"><div id="td_g"></div><div class="sp"><b>Autopilot</b> <span class="mut sm">agents + ISA run the file · you get the licensed decisions</span><div id="td_flow" style="margin-top:6px"></div></div><div style="text-align:center"><div style="font-size:30px;font-weight:700" id="td_n">0</div><div class="mut sm">need you now</div><a class="btn sm" href="#autopilot" style="margin-top:6px;display:inline-block">Open queue</a></div></div></div>`+h0();
 PAGE.today.mount=function(v){m0?.call(this,v);vizGauge($("#td_g"),apMinutes(apRules()).pct,{label:"runs without you",size:130,zones:[[60,"var(--bad)"],[79,"var(--warn)"],[101,"var(--good)"]]});vizFlow($("#td_flow"),AP_STAGES.filter((s,i)=>i%2===0||s.who==="Steven").slice(0,6).map(s=>({l:s.l.split(" ")[0]+" "+(s.l.split(" ")[1]||""),who:s.who.split(" ")[0],color:s.color})));animateNum($("#td_n"),apQueue().length,{fmt:n=>Math.round(n)})}}
{const m0=PAGE.aus.mount;PAGE.aus.mount=function(v){m0?.call(this,v);const out=$("#au_out");if(!out)return;const obs=new MutationObserver(()=>{if(out.querySelector(".au-gauge"))return;const cards=[...out.querySelectorAll(".card")];if(!cards.length)return;cards.forEach(c=>{const tag=c.querySelector("h3 .tag");if(!tag)return;const m=(c.querySelector("h3 .mut")||{}).textContent?.match(/risk index (\d+)/);const score=m?+m[1]:30;const cls=tag.classList.contains("good")?"good":tag.classList.contains("warn")?"warn":"bad";const pct=cls==="good"?Math.max(70,100-score*1.2):cls==="warn"?Math.max(40,80-score):Math.max(5,40-score*0.5);const g=document.createElement("div");g.className="au-gauge";g.style.cssText="float:right;margin:-6px 0 0 10px";c.insertBefore(g,c.children[1]||null);vizGauge(g,Math.round(pct),{label:"approval likelihood",size:120})})});obs.observe(out,{childList:true});cleanups.push(()=>obs.disconnect())}}
{const pages=PAGES;const op=pages.find(p=>p[0]==="Operate");if(op&&!op[1].some(x=>x[0]==="autopilot"))op[1].splice(1,0,["autopilot","Autopilot 80/20"]);const li=pages.find(p=>p[0]==="Loan Intelligence");if(li){if(!li[1].some(x=>x[0]==="exam"))li[1].splice(li[1].findIndex(x=>x[0]==="va")+1,0,["exam","VA Practice Exam"]);if(!li[1].some(x=>x[0]==="sims"))li[1].splice(li[1].findIndex(x=>x[0]==="calc")+1,0,["sims","Simulators"])}}
{const c0=coachCorpus;coachCorpus=function(){const out=c0();EXAM_BANK.forEach(q=>out.push({src:`Exam Q ch.${q.ch}`,t:`${q.q} Answer: ${q.o[q.a]}. ${q.e} (${q.c})`}));AP_RULES_DEFAULT.forEach(r=>out.push({src:`Autopilot rule — ${r.trigger}`,t:`Agent: ${r.agent}. ISA: ${r.isa}. Steven: ${r.steven}`}));return out}}
